 if(id==='summary'&&data.a.length<2)throw Error('Sample variance requires at least two observations.');
 for(const key of ['conf','predconf','alpha'])if(o[key]!==undefined)WStats.probability(o[key],key==='alpha'?'Significance level':'Confidence level',true);
